(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6z"/>',home:'<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',medical:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z"/>',cup:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM17 9h2a3 3 0 0 1 0 6h-2M7 3v2m5-2v2"/>',tent:'<path d="m3 20 9-17 9 17zM8 20l4-8 4 8"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',tool:'<path d="m14 6 4 4m-7-5a6 6 0 0 0-5 8L2 18l4 4 5-5a6 6 0 0 0 8-8l-5 5-4-4 5-5z"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',cloud:'<path d="M7 18H6a4 4 0 0 1-1-8 7 7 0 0 1 13-1 4.5 4.5 0 0 1 0 9h-1M12 11v10m-3-3 3 3 3-3"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M8 5v14M16 5v14"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11z"/>',bag:'<path d="M8 3h8l-2 4c8 9 7 14-2 14S2 16 10 7zM9 7h6M12 11v6m-3-3h6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',plus:'<path d="M12 4v16M4 12h16"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="5" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8 10 7-4M8 14l7 4"/>',sos:'<path d="M5 17v-5a7 7 0 0 1 14 0v5M3 17h18v4H3zM12 1v2M2 5l2 2m18-2-2 2M1 12h2m18 0h2"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',filter:'<path d="M3 6h18M6 12h12M9 18h6"/>',rotate:'<path d="M4 10a8 8 0 1 1 1 8M4 3v7h7"/>',expand:'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',edit:'<path d="m15 3 6 6-12 12H3v-6zM12 6l6 6"/>',warning:'<path d="m12 3 10 18H2zM12 9v5m0 3v.1"/>',book:'<path d="M12 5c-4-3-10-2-10-2v16s6-1 10 2c4-3 10-2 10-2V3s-6-1-10 2zM12 5v16"/>',location:'<path d="M19 10c0 6-7 11-7 11S5 16 5 10a7 7 0 0 1 14 0z"/><circle cx="12" cy="10" r="2"/>',volume:'<path d="m10 4-6 5H1v6h3l6 5zM15 7a7 7 0 0 1 0 10m3-13a11 11 0 0 1 0 16"/>',leaf:'<path d="M20 3C7 1 0 12 7 18c7 7 15-3 13-15zM5 21 16 9"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.1"/>'};
const ic=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${paths[n]||paths.book}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('tk-'+k))??f;}catch{return f;}};
function write(k,v){try{localStorage.setItem('tk-'+k,JSON.stringify(v));return true;}catch{toast('Bộ nhớ đã đầy. Hãy xuất dữ liệu để giữ bản sao.');return false;}}
let saved=read('saved',[]),completed=read('completed',[]),contributions=read('contributions',[]),draft=read('draft',{}),theme=read('theme','light'),name=read('name','Bạn khám phá');
let currentCat='all',query='',toolSelection=[],wizardStep=0,activeStep=0,stage=null,autoTimer=null,detailTip=null,situation='lost',quizIndex=0,quizScore=0,quizAnswered=false,manageFilter='all',mediaUrl=null,installedPacks=[],installPrompt=null;
let signalTimer=null,audio=null,osc=null,signalMode=null;let toastTimer;
const app=$('#app'),modal=$('#modal');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300);}
const catName=id=>CATEGORIES.find(c=>c[0]===id)?.[1]||'Mẹo đời sống';
const brand=()=>'<a class="brand" href="#/" aria-label="Túi Khôn — Trang chủ"><img src="assets/icon.svg" alt=""><span><strong>Túi Khôn</strong><small>Mẹo nhỏ, bản lĩnh lớn.</small></span></a>';
function navLink(route,label,icon,active){return`<a href="#/${route}" class="${active?'active':''}">${icon?ic(icon):''}${label}</a>`;}
function shell(content,route){
 document.documentElement.dataset.theme=theme;
 app.innerHTML=`<header><div class="wrap topbar">${brand()}<form class="search" id="search-form" role="search">${ic('search')}<input id="global-search" type="search" name="q" placeholder="Bạn muốn học mẹo gì hôm nay?" aria-label="Tìm kiếm mẹo" value="${esc(query)}"><kbd>⌘ K</kbd></form><div class="tools"><div class="mode-switch" aria-label="Chế độ giao diện"><button data-action="theme" data-value="light" class="${theme==='light'?'selected':''}" aria-pressed="${theme==='light'}">${ic('sun')}Đời sống</button><button data-action="theme" data-value="dark" class="${theme==='dark'?'selected':''}" aria-pressed="${theme==='dark'}">${ic('compass')}Sinh tồn</button></div><a class="connection" href="#/offline"><i class="status-dot"></i><span id="connection-label">${navigator.onLine?'Sẵn sàng khám phá':'Đang ngoại tuyến'}</span></a><a class="icon-btn" href="#/saved" aria-label="Mẹo đã lưu">${ic('bookmark')}</a><a href="#/manage" class="avatar" aria-label="Hồ sơ cá nhân">${esc(name.slice(0,1).toUpperCase())}</a><button class="icon-btn mobile-menu" data-action="menu" aria-label="Mở menu">${ic('menu')}</button></div></div><div class="navline"><nav class="wrap nav" aria-label="Điều hướng chính">${navLink('','Khám phá',null,route==='home')}${navLink('library','Mẹo đời sống',null,route==='library')}${navLink('survival','Sinh tồn & dã ngoại',null,route==='survival')}${navLink('emergency','Sơ cứu & an toàn',null,route==='emergency')}${navLink('offline','Cẩm nang ngoại tuyến',null,route==='offline')}${navLink('contribute','Đóng góp mẹo','plus',route==='contribute')}${navLink('manage','Góc của tôi','user',route==='manage')}</nav></div></header><main id="main" class="wrap page" tabindex="-1">${content}</main><footer class="wrap footer">${brand()}<div class="footer-links"><button data-action="sources">Nguồn & kiểm chứng</button><button data-action="about">Về Túi Khôn</button><button data-action="profile">Cài đặt cá nhân</button></div><span class="muted">Học điều nhỏ. Sẵn sàng cho điều lớn.</span></footer><button class="sos-float" data-action="sos">${ic('sos')}Trợ giúp SOS</button><nav class="bottomnav" aria-label="Điều hướng điện thoại">${navLink('','Khám phá','compass',route==='home')}${navLink('library','Thư viện','grid',route==='library')}${navLink('saved','Đã lưu','bookmark',route==='saved')}${navLink('offline','Ngoại tuyến','download',route==='offline')}<button data-action="sos">${ic('sos')}SOS</button></nav>`;
}
function tipCard(t){return`<article class="tip-card"><div class="card-media"><a href="#/tip/${t.id}" aria-label="${esc(t.title)}"><img src="assets/${t.image}.jpg" alt="${esc(t.title)} — ảnh minh họa" loading="lazy" width="360" height="220"></a><span class="duration">${ic('clock')} ${esc(t.time)}</span><button class="save-btn ${saved.includes(t.id)?'saved':''}" data-action="save" data-id="${t.id}" aria-label="${saved.includes(t.id)?'Bỏ lưu':'Lưu'} ${esc(t.title)}" aria-pressed="${saved.includes(t.id)}">${ic('bookmark')}</button></div><div class="card-body"><div class="card-meta">${catName(t.cat)}<span>·</span><span>${esc(t.level)}</span></div><a href="#/tip/${t.id}"><h3>${esc(t.title)}</h3></a><div class="card-bottom"><span class="practice-mark">${ic(t.url?'shield':'book')}${esc(t.tag)}</span><span>${ic('rotate')}3D tương tác</span></div></div></article>`;}
function chips(){return`<div class="category-scroll">${CATEGORIES.map(([id,label,icon])=>`<button class="chip ${currentCat===id?'active':''}" data-action="category" data-id="${id}" aria-pressed="${currentCat===id}">${ic(icon)}${label}</button>`).join('')}</div>`;}
function filteredTips(){const q=normalize(query);return TIPS.filter(t=>(currentCat==='all'||t.cat===currentCat||(currentCat==='life'&&['life','kitchen','tech','diy'].includes(t.cat)))&&(!q||normalize(t.title+' '+t.desc+' '+t.tools.join(' ')+' '+catName(t.cat)).includes(q))&&(!toolSelection.length||t.tools.some(x=>toolSelection.includes(x))));}
function normalize(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();}
function empty(title,desc,link='#/library',label='Khám phá thư viện'){return`<div class="empty">${ic('book')}<h3>${title}</h3><p>${desc}</p><a class="btn secondary" href="${link}">${label}${ic('arrow')}</a></div>`;}
function home(){const featured=TIPS[0];shell(`<div class="intro row between"><div><h1>Hôm nay, học một điều hay.</h1><p>Từ căn bếp nhỏ đến chuyến đi xa — luôn có một mẹo dành cho bạn.</p></div><a href="#/saved" class="date">${ic('bookmark')}Sổ tay của bạn · ${saved.length} mẹo</a></div><div class="feature-grid"><article class="feature"><img src="assets/forest.jpg" alt="Ánh nắng xuyên qua khu rừng xanh" width="900" height="500"><div class="feature-top"><span class="photo-label">${ic('compass')}Cẩm nang sinh tồn</span><span class="photo-label">${ic('rotate')}Thực hành 3D</span></div><div class="feature-content"><h2>Một chiếc chai.<br>Thêm một kỹ năng.</h2><p>Khám phá cách xếp các tầng lọc cặn nước và những giới hạn an toàn cần biết.</p><div class="row feature-bottom"><a href="#/tip/${featured.id}" class="btn">Khám phá cách làm${ic('arrow')}</a><span class="light">3 bước rõ ràng · Xoay 360°</span></div></div></article><aside class="side-feature">${ic('bag')}<h2>Sẵn sàng cả khi <br>không có sóng.</h2><p>Mang theo cẩm nang thiết yếu. Đọc hướng dẫn, xoay mô hình, học kỹ năng ngay cả khi ngoại tuyến.</p><a class="btn secondary" href="#/offline">${ic('download')}Chuẩn bị túi ngoại tuyến</a><div class="offline-details"><span>${ic('check')}Không cần tài khoản</span><span>${ic('wifi')}PWA</span></div></aside></div><div class="quickline"><div class="row">${ic('shield')}<span><strong>Hiểu đúng trước khi làm.</strong> Nguồn tham khảo và lưu ý đi cùng mỗi mẹo.</span></div><span class="divider"></span><a href="#/emergency">${ic('medical')}Cần trợ giúp ngay?${ic('arrow')}</a></div><section class="section"><div class="section-head"><div><h2>Thêm khéo léo, bớt loay hoay.</h2><p>Những kỹ năng nhỏ đáng có trong sổ tay của bạn.</p></div><a href="#/library" class="btn text">Xem thư viện${ic('arrow')}</a></div><div class="filterbar">${chips()}</div><div class="cards" id="tip-results">${TIPS.slice(0,4).map(tipCard).join('')}</div></section><section class="section bottom-grid"><div class="tool-panel"><div class="row between"><h2>Bạn đang có gì trong tay?</h2>${ic('tool')}</div><p>Chọn dụng cụ sẵn có. Tìm ngay một mẹo có thể bắt đầu.</p><div class="tool-options">${['Chai nhựa','Dây thun','Khăn sạch','Dây thừng','Bật lửa','Dây sạc'].map(t=>`<button class="chip ${toolSelection.includes(t)?'active':''}" data-action="tool" data-value="${t}" aria-pressed="${toolSelection.includes(t)}">${ic('plus')}${t}</button>`).join('')}</div><button class="btn text" data-action="tool-search">Tìm mẹo phù hợp${ic('arrow')}</button></div><div class="quiz-panel"><div class="quiz-visual">${ic('compass')}<h2>Nếu là bạn, bạn sẽ làm gì?</h2></div><p>Thử sức với 3 tình huống. Học thêm một chút để bình tĩnh hơn khi cần.</p><a class="btn text" href="#/quiz">Thử thách kỹ năng${ic('arrow')}</a></div></section>`,'home');}
function library(isSaved=false){const tips=isSaved?TIPS.filter(t=>saved.includes(t.id)):filteredTips();shell(`<div class="title-row"><div><h1>${isSaved?'Sổ tay của bạn':'Thư viện mẹo hay'}</h1><p>${isSaved?'Những kỹ năng bạn muốn mang theo, luôn ở một chỗ.':'Tìm theo tình huống, chủ đề hoặc những dụng cụ đang có.'}</p></div>${isSaved?'<a href="#/offline" class="btn secondary">'+ic('download')+'Lưu ngoại tuyến</a>':'<div class="row"><a class="btn secondary" href="#/practice/water">'+ic('play')+'Thực hành nhanh</a><button class="btn secondary" data-action="tool-modal">'+ic('filter')+'Lọc dụng cụ</button></div>'}</div>${isSaved?'':`<form class="search full-width" id="library-search" style="max-width:100%;margin-bottom:20px">${ic('search')}<input name="q" type="search" aria-label="Tìm trong thư viện" placeholder="Ví dụ: nước, đi rừng, dây sạc…" value="${esc(query)}"></form><div class="filterbar">${chips()}</div>${toolSelection.length?`<p class="search-summary">Có dụng cụ: ${esc(toolSelection.join(', '))} · <button class="text-link" data-action="clear-tools">Bỏ bộ lọc</button></p>`:''}`}<p class="search-summary" id="result-count">${tips.length} mẹo${query?' cho “'+esc(query)+'”':''}</p><div class="cards" id="tip-results">${tips.length?tips.map(tipCard).join(''):empty(isSaved?'Một sổ tay đang chờ bạn.':'Chưa tìm thấy mẹo phù hợp.',isSaved?'Bấm biểu tượng dấu trang trên mẹo bạn muốn lưu.':'Thử từ khóa ngắn hơn hoặc bỏ bớt bộ lọc.')}</div>` ,isSaved?'saved':'library');}
function detail(id){const t=TIPS.find(x=>x.id===id);if(!t){shell(empty('Không tìm thấy mẹo.','Mẹo này có thể đã được thay đổi.'),'detail');return;}detailTip=t;activeStep=0;
shell(`<div class="breadcrumb"><a href="#/">Khám phá</a>${ic('chevron')}<a href="#/library">${catName(t.cat)}</a>${ic('chevron')}<span>Hướng dẫn thực hành</span></div><div class="detail-header"><div><div class="row"><span class="tag">${catName(t.cat)}</span><span class="small muted">${ic('clock')}${esc(t.time)} · ${esc(t.level)}</span></div><h1>${esc(t.title)}</h1><p>${esc(t.desc)}</p><div class="article-source">${ic('shield')}<div><strong>${esc(t.source)}</strong><p>Nguồn công khai · Cập nhật nội dung 19/10/2026</p></div>${t.url?`<a href="${t.url}" target="_blank" rel="noopener">Đọc nguồn ↗</a>`:''}</div><div class="author"><span class="avatar">TK</span><div>Ban biên tập Túi Khôn<small class="muted" style="display:block">Cẩm nang tham khảo · Chưa có thẩm định độc lập</small></div><div class="row article-actions"><button class="btn secondary" data-action="save" data-id="${t.id}">${ic('bookmark')}<span>${saved.includes(t.id)?'Đã lưu':'Lưu mẹo'}</span></button><button class="icon-btn" data-action="share" data-id="${t.id}" aria-label="Chia sẻ mẹo">${ic('share')}</button></div></div></div><aside class="offline-box"><h3>${ic('cloud')}Mang mẹo này theo bạn</h3><p>Gói ngoại tuyến chứa hướng dẫn, hình minh họa và mô hình 3D, dùng khi không có mạng.</p><div class="row between small"><span>Trạng thái gói</span><span id="detail-pack-state">${installedPacks.includes('all')?'Đã lưu':'Chưa tải'}</span></div><div class="progress"><span style="width:${installedPacks.includes('all')?100:0}%"></span></div><button class="btn" data-action="download-pack" data-id="all">${ic('download')}Tải cẩm nang ngoại tuyến</button><p style="margin-bottom:0">${ic('check')}Không cần đăng nhập · Lưu trên thiết bị</p></aside></div><div class="section-head"><h2>Nhìn rõ. Làm từng bước.</h2><span class="tag neutral">${ic('rotate')}Mô hình tương tác 360°</span></div><div class="detail-grid"><div class="stage-container"><div class="stage" id="stage"><div class="stage-status">${ic('rotate')}Kéo để xoay mô hình</div><div class="stage-label" id="stage-label">${esc(t.steps[0][0])}</div><div class="stage-toolbar"><button class="icon-btn" data-action="reset-stage" aria-label="Đặt lại góc nhìn">${ic('rotate')}</button><button class="icon-btn" data-action="fullscreen" aria-label="Phóng to mô hình">${ic('expand')}</button></div><span class="stage-help">Mô phỏng cấu tạo · Chọn bước để khám phá</span></div><div class="stage-controls"><button class="btn secondary" data-action="autoplay">${ic('play')}<span>Tự động chạy</span></button><div class="step-track" aria-label="Chọn bước">${t.steps.map((s,i)=>`<button class="${i===0?'active':''}" data-action="step" data-step="${i}" aria-label="Bước ${i+1}: ${esc(s[0])}"></button>`).join('')}</div><span class="small muted num" id="step-count">1 / 3</span></div></div><div><div class="preparation"><h3>Chuẩn bị trong tầm tay</h3><div class="tool-options">${t.tools.map(x=>`<span class="tool-item">${esc(x)}</span>`).join('')}</div></div><div class="steps">${t.steps.map((s,i)=>`<button class="step-btn ${i===0?'active':''}" data-action="step" data-step="${i}" aria-pressed="${i===0}"><span class="step-number">${i+1}</span><span><strong>${esc(s[0])}</strong><p>${esc(s[1])}</p></span></button>`).join('')}</div><div class="notice">${ic('warning')}<div><strong>Lưu ý trước khi làm</strong><p>${esc(t.warning)}</p></div></div><label class="checklist"><input type="checkbox" data-complete="${t.id}" ${completed.includes(t.id)?'checked':''}>Tôi đã đọc đủ 3 bước và lưu ý an toàn</label></div></div><section class="section"><div class="section-head"><h2>Thêm vào hành trang.</h2><a class="btn text" href="#/library">Xem tất cả${ic('arrow')}</a></div><div class="related-grid">${TIPS.filter(x=>x.id!==t.id).slice(0,4).map(tipCard).join('')}</div></section><section class="section panel"><h3>Góp ý cho cẩm nang</h3><p class="small" style="margin:8px 0 14px">Phát hiện nội dung cần làm rõ? Gửi ghi chú để lưu cùng mẹo trên thiết bị của bạn.</p><form id="feedback-form" class="row"><input aria-label="Ghi chú của bạn" name="feedback" required maxlength="1000" placeholder="Nội dung cần điều chỉnh…" class="filter-select" style="flex:1;min-width:0"><button class="btn secondary" type="submit">Lưu góp ý</button></form><div id="feedback-notes">${feedbackNotes(t.id)}</div></section>`,'detail');stage=createStage($('#stage'),t.model);}
function feedbackNotes(id){return read('feedback',[]).filter(n=>n.tip===id).slice(-5).map(n=>`<div class="feedback-note"><small>Ghi chú của bạn · ${esc(new Date(n.date).toLocaleDateString('vi-VN'))}</small><p>${esc(n.text)}</p></div>`).join('');}
function setStep(n){activeStep=n;stage?.setStep(n);$$('.step-btn').forEach((el,i)=>{el.classList.toggle('active',i===n);el.setAttribute('aria-pressed',i===n);});$$('.step-track button').forEach((el,i)=>el.classList.toggle('active',i===n));$('#step-count').textContent=`${n+1} / 3`;$('#stage-label').textContent=detailTip.steps[n][0];}
function manage(){const list=contributions.filter(c=>manageFilter==='all'||c.status===manageFilter);shell(`<section class="panel profile-panel"><div class="profile-main"><span class="avatar">${esc(name.slice(0,1).toUpperCase())}</span><div><h1>${esc(name)}</h1><p>Góp một kinh nghiệm nhỏ, làm dày thêm hành trang chung.</p><button class="btn text" data-action="profile" style="font-size:11px;min-height:25px">Chỉnh sửa hồ sơ</button></div><a href="#/contribute" class="btn">${ic('plus')}Đóng góp mẹo mới</a></div><div class="stats">${[['Mẹo đã gửi',contributions.filter(c=>c.status==='pending').length,'Đang chờ thẩm định'],['Bản nháp',contributions.filter(c=>c.status==='draft').length,'Có thể tiếp tục chỉnh sửa'],['Mẹo đã lưu',saved.length,'Trong sổ tay cá nhân'],['Kỹ năng đã đọc',completed.length,'Đã xác nhận đọc đủ hướng dẫn']].map(([label,value,note])=>`<div class="stat"><p>${label}</p><strong class="num">${value.toString().padStart(2,'0')}</strong><small>${note}</small></div>`).join('')}</div></section><div class="dashboard-layout"><section class="panel"><div class="section-head"><h2>Đóng góp của bạn</h2><span class="small muted">${contributions.length} mẹo</span></div><div class="category-scroll">${[['all','Tất cả'],['pending','Chờ thẩm định'],['draft','Bản nháp']].map(([id,label])=>`<button data-action="manage-filter" data-id="${id}" class="chip ${manageFilter===id?'active':''}">${label}</button>`).join('')}</div>${list.length?list.map(c=>`<article class="contribution-row"><div><span class="tag ${c.status==='pending'?'warning':'neutral'}">${c.status==='pending'?'Chờ thẩm định':'Bản nháp'} · ${esc(c.id)}</span><h3>${esc(c.title||'Mẹo chưa đặt tên')}</h3><p>${catName(c.cat)} · ${new Date(c.updated).toLocaleDateString('vi-VN')} · ${c.mediaName?'Có tệp minh họa':'Chưa có tệp'}</p></div><div class="row-actions"><button class="icon-btn" data-action="preview-contribution" data-id="${esc(c.id)}" aria-label="Xem ${esc(c.title)}">${ic('book')}</button><button class="icon-btn" data-action="edit-contribution" data-id="${esc(c.id)}" aria-label="Chỉnh sửa ${esc(c.title)}">${ic('edit')}</button></div></article>`).join(''):empty('Kinh nghiệm đầu tiên của bạn?','Một mẹo hữu ích có thể bắt đầu từ việc bạn làm mỗi ngày.','#/contribute','Viết mẹo đầu tiên')}</section><aside class="panel"><h3>Hành trình đóng góp</h3><ol class="emergency-steps small"><li>Chuẩn bị nội dung và nguồn.</li><li>Kiểm tra độ đầy đủ biểu mẫu.</li><li>Lưu bản gửi chờ người duyệt.</li></ol><p class="quality-note">Dữ liệu của bạn đang lưu trên trình duyệt này. Chưa kết nối hệ thống thẩm định hoặc tài khoản cộng đồng.</p><div class="backup-actions"><button class="btn secondary full-width" data-action="export">${ic('download')}Xuất dữ liệu cá nhân</button><label class="btn text" style="cursor:pointer">Nhập bản sao<input id="import-data" type="file" accept="application/json" hidden></label></div></aside></div>`,'manage');}
function draftScore(){const fields=[draft.title,draft.cat,draft.desc,draft.tools,draft.s1,draft.s2,draft.s3,draft.warning,draft.source,draft.mediaName];return Math.round(fields.filter(x=>typeof x==='string'&&x.trim()).length/fields.length*100);}
function field(key,label,placeholder='',type='text',required=false){return`<label class="form-field"><span>${label}${required?' *':''}</span>${type==='textarea'?`<textarea name="${key}" placeholder="${placeholder}" ${required?'required':''} maxlength="2500">${esc(draft[key]||'')}</textarea>`:`<input type="${type}" name="${key}" value="${esc(draft[key]||'')}" placeholder="${placeholder}" ${required?'required':''} maxlength="500">`}</label>`;}
function contribution(){let body='';if(wizardStep===0)body=`<h2>Bắt đầu từ một kinh nghiệm.</h2><p class="small" style="margin-top:8px">Đặt tên rõ ràng và chọn nhóm phù hợp cho mẹo của bạn.</p>${field('title','Tên mẹo','Ví dụ: Gấp áo mưa gọn trong ba lô','text',true)}<span class="field-label">Nhóm nội dung *</span><div class="form-options">${[['life','Mẹo đời sống','Gia đình, nhà bếp và các tiện ích mỗi ngày.'],['survival','Sinh tồn & dã ngoại','Kỹ năng ngoài trời, chuẩn bị và ứng phó.']].map(([value,title,desc])=>`<label><input type="radio" name="cat" value="${value}" ${draft.cat===value?'checked':''} required>${title}<p>${desc}</p></label>`).join('')}</div>${field('tools','Dụng cụ cần có','Ngăn cách bằng dấu phẩy','text',true)}`;
if(wizardStep===1)body=`<h2>Cho mọi người nhìn thấy cách làm.</h2>${field('desc','Mô tả mẹo','Mẹo giải quyết tình huống nào?','textarea',true)}<span class="field-label">Ảnh hoặc clip minh họa (tùy chọn)</span><div class="upload">${ic('upload')}<p>Chọn video tối đa 60 giây hoặc ảnh JPG/PNG/WebP.<br>Tối đa 30 MB · Chỉ lưu trên thiết bị này.</p><input id="media-upload" type="file" accept="video/mp4,video/webm,image/jpeg,image/png,image/webp" aria-label="Chọn tệp minh họa"><div id="media-preview">${draft.mediaName?`<p>${ic('check')}${esc(draft.mediaName)}</p>`:''}</div></div>${field('source','Nguồn tham khảo','Tên tài liệu hoặc URL nguồn đáng tin cậy','text',true)}`;
if(wizardStep===2)body=`<h2>Ba bước dễ hiểu, đủ lưu ý.</h2><p class="small" style="margin-top:7px">Viết cụ thể để người mới có thể đọc và hiểu.</p>${field('s1','Bước 1','Chuẩn bị và thao tác đầu tiên','textarea',true)}${field('s2','Bước 2','Thao tác tiếp theo','textarea',true)}${field('s3','Bước 3','Hoàn thành và kiểm tra kết quả','textarea',true)}${field('warning','Rủi ro và điều cần tránh','Nêu giới hạn của mẹo và trường hợp không nên làm','textarea',true)}`;
if(wizardStep===3)body=`<h2>Xem lại trước khi gửi.</h2><div class="review-section"><span class="tag">${catName(draft.cat)}</span><h3 style="margin-top:9px">${esc(draft.title)}</h3><p>${esc(draft.desc)}</p><p>Dụng cụ: ${esc(draft.tools)}</p></div>${[1,2,3].map(i=>`<div class="review-section"><strong>Bước ${i}</strong><p>${esc(draft['s'+i])}</p></div>`).join('')}<div class="notice">${ic('warning')}<p>${esc(draft.warning)}</p></div><p class="source-row">Nguồn: ${esc(draft.source)}</p><label class="checklist"><input type="checkbox" id="consent" required>Tôi đã rà soát nội dung, quyền sử dụng tệp và hiểu rằng mẹo cần người có chuyên môn thẩm định trước khi xuất bản.</label>`;
shell(`<div class="title-row"><div><h1>Góp một mẹo, thêm một kỹ năng.</h1><p>Mỗi kinh nghiệm đều bắt đầu từ nội dung rõ ràng và sự cẩn trọng.</p></div><button class="btn secondary" data-action="save-draft">${ic('bookmark')}Lưu bản nháp</button></div><div class="form-progress">${['Thông tin & phân loại','Nội dung & minh họa','Hướng dẫn & an toàn','Xem lại & gửi'].map((s,i)=>`<button class="form-step ${wizardStep===i?'current':wizardStep>i?'done':''}" data-action="wizard-goto" data-step="${i}" ${i>wizardStep?'disabled':''}><span class="step-number">${wizardStep>i?ic('check'):i+1}</span>${s}</button>`).join('')}</div><div class="builder-layout"><form class="panel" id="contribution-form">${body}<div class="form-actions"><button type="button" class="btn ghost" data-action="wizard-back" ${wizardStep===0?'disabled':''}>Quay lại</button><button class="btn" type="submit">${wizardStep===3?'Gửi chờ thẩm định':'Tiếp tục'}${ic('arrow')}</button></div></form><aside class="panel"><div class="row between"><h3>Kiểm tra nội dung</h3>${ic('shield')}</div><div class="quality-number num" id="quality-number">${draftScore()}<small> / 100</small></div><p class="small">Mức độ đầy đủ của biểu mẫu</p><div class="progress"><span id="quality-progress" style="width:${draftScore()}%"></span></div><div id="quality-items">${qualityItems()}</div><p class="quality-note">Kiểm tra tự động chỉ phát hiện trường còn thiếu. Đây không phải đánh giá an toàn bằng AI hay xác nhận từ chuyên gia.</p><div class="notice">${ic('book')}<p>Mẹo sinh tồn và sơ cứu cần nguồn phù hợp. Không sao chép lời khuyên nguy hiểm từ mạng xã hội.</p></div></aside></div>`,'contribute');if(wizardStep===1&&draft.mediaKey)showStoredMedia(draft.mediaKey);}
function qualityItems(){return[['Tên & phân loại',draft.title&&draft.cat],['Mô tả & dụng cụ',draft.desc&&draft.tools],['Đủ 3 bước',draft.s1&&draft.s2&&draft.s3],['Lưu ý & nguồn',draft.warning&&draft.source],['Tệp minh họa',draft.mediaName]].map(([label,ok])=>`<div class="quality-item"><span>${label}</span><span class="muted">${ic(ok?'check':'plus')}</span></div>`).join('');}
function captureDraft(){const f=$('#contribution-form');if(f){for(const [k,v]of new FormData(f))if(typeof v==='string')draft[k]=v.trim();write('draft',draft);}}
function refreshQuality(){if($('#quality-number')){$('#quality-number').innerHTML=draftScore()+'<small> / 100</small>';$('#quality-progress').style.width=draftScore()+'%';$('#quality-items').innerHTML=qualityItems();}}
function saveContribution(status){captureDraft();const id=draft.id||'TK-'+Date.now().toString(36).toUpperCase();const c={...draft,id,status,updated:new Date().toISOString()};const next=[c,...contributions.filter(x=>x.id!==id)];if(!write('contributions',next))return false;contributions=next;draft={...c};write('draft',draft);return true;}
function offline(){shell(`<div class="title-row"><div><h1>Hành trang không cần sóng.</h1><p>Tải trước khi đi. Đọc hướng dẫn và thực hành 3D ngay cả khi mất mạng.</p></div><button class="btn secondary" data-action="install">${ic('download')}Cài ứng dụng</button></div><div class="offline-progress"><div class="row between"><p id="offline-status">${installedPacks.includes('all')?'Cẩm nang đã lưu trên thiết bị này.':'Chọn một gói để lưu vào thiết bị này.'}</p><span class="small" id="offline-percent">${installedPacks.includes('all')?'100%':''}</span></div><div class="progress"><span id="offline-bar" style="width:${installedPacks.includes('all')?100:0}%"></span></div></div><div class="offline-list">${[['all','Túi Khôn trọn bộ','10 mẹo, đủ mô hình 3D và bộ hướng dẫn SOS.','forest','10 mẹo · Toàn bộ tài nguyên'],['survival','Bình tĩnh giữa thiên nhiên','Lọc cặn, nhóm lửa, chọn chỗ trú và chuẩn bị hành trang.','camp','6 bài · Kèm cẩm nang SOS'],['life','Khéo léo trong từng ngày','Mở nắp lọ, giữ dây sạc bền và mẹo trong căn bếp.','kitchen','4 bài · Thực hành tại nhà']].map(([id,title,desc,img,count])=>`<article class="pack"><img src="assets/${img}.jpg" alt="${title} — ảnh minh họa"><h2>${title}</h2><p>${desc}</p><div class="row between small muted"><span>${count}</span><span>${installedPacks.includes(id)||installedPacks.includes('all')?'Đã lưu ✓':'Chưa tải'}</span></div><button class="btn ${installedPacks.includes(id)?'secondary':''}" data-action="download-pack" data-id="${id}">${ic('download')}${installedPacks.includes(id)?'Cập nhật gói':'Tải gói ngoại tuyến'}</button></article>`).join('')}</div><div class="bottom-grid section"><section class="panel"><h2>Kiểm tra trước chuyến đi.</h2><ol class="emergency-steps"><li><strong>Tải và chờ hoàn tất</strong><p>Chỉ thông báo “Đã lưu” sau khi toàn bộ tài nguyên được ghi vào bộ nhớ ngoại tuyến.</p></li><li><strong>Mở lại khi đã tắt mạng</strong><p>Thử truy cập mẹo và mô hình 3D trước chuyến đi. Trình duyệt có thể xóa dữ liệu khi thiết bị thiếu bộ nhớ.</p></li><li><strong>Chuẩn bị thêm bản văn bản</strong><p>Lưu cẩm nang .txt để đọc bằng các ứng dụng khác trên điện thoại.</p></li></ol><button class="btn secondary" data-action="download-text">${ic('download')}Xuất cẩm nang .txt</button></section><aside class="panel"><h3>Dữ liệu của bạn</h3><p class="quality-note">Các gói và sổ tay lưu tại trình duyệt. Dùng xuất dữ liệu để sao lưu ghi chú, mẹo đã lưu và đóng góp.</p><div class="backup-actions"><button class="btn secondary" data-action="export">${ic('download')}Xuất dữ liệu</button><button class="btn text" data-action="cache-info">Xem dung lượng đã dùng</button></div><p class="small muted" id="storage-info"></p></aside></div>`,'offline');}
const situations={lost:{icon:'compass',title:'Bình tĩnh khi nhận ra mình bị lạc',steps:[['Dừng lại và ổn định','Đừng đi tiếp trong hoảng loạn. Hít thở, kiểm tra người đi cùng, nước và đồ giữ ấm.'],['Quan sát và giữ vị trí an toàn','Đối chiếu bản đồ và mốc địa hình. Tránh vách dốc, dòng chảy và nơi có nguy cơ lũ; đánh dấu vị trí dễ nhận biết.'],['Liên lạc và phát tín hiệu','Gửi vị trí cho người tin cậy khi có kết nối. Nếu không xác định được đường về an toàn, giữ ở nơi an toàn, dễ được tìm thấy.']],source:'National Park Service · If you get lost',url:'https://www.nps.gov/articles/000/hiking-safety.htm'},water:{icon:'cup',title:'Ưu tiên nguồn nước an toàn',steps:[['Tìm nước đã đóng chai','Ưu tiên nguồn đáng tin và phân bổ lượng nước đang có.'],['Không tin vào độ trong','Lọc cặn không có nghĩa đã loại vi sinh hoặc hóa chất. Không uống nước nghi nhiễm nhiên liệu hay hóa chất.'],['Xử lý đúng trước khi uống','Đọc hướng dẫn CDC trong bài lọc cặn. Đun sôi không loại bỏ chất độc hóa học.']],tip:'water'},cold:{icon:'tent',title:'Giữ khô và giữ ấm',steps:[['Tránh gió và mưa','Tìm nơi trú an toàn; tránh lòng suối và cây khô.'],['Thay đồ ướt nếu có thể','Mặc nhiều lớp khô và cách cơ thể khỏi đất ẩm.'],['Tìm hỗ trợ khi có dấu hiệu nguy hiểm','Lú lẫn, lơ mơ hoặc mất phối hợp cần trợ giúp y tế ngay. Không dùng đồ uống có cồn.']],tip:'shelter'},snake:{icon:'medical',title:'Nghi rắn cắn: tìm hỗ trợ y tế ngay',steps:TIPS.find(x=>x.id==='snake').steps,tip:'snake'},battery:{icon:'bolt',title:'Dành pin cho việc quan trọng',steps:[['Gửi tin cần thiết trước','Khi còn sóng, báo vị trí gần nhất, tình trạng và lịch trình cho người tin cậy.'],['Bật chế độ tiết kiệm pin','Giảm sáng, đóng tác vụ không cần thiết; giữ điện thoại khô và tránh nhiệt độ cực đoan.'],['Dùng cẩm nang đã tải','Mở hướng dẫn ngoại tuyến. Còi điện tử và đèn màn hình sẽ tiêu thụ pin, chỉ dùng khi cần.']]},signal:{icon:'sos',title:'Phát tín hiệu để được chú ý',steps:[['Chọn vị trí an toàn, dễ thấy','Giữ ở nơi thoáng nếu điều kiện cho phép; chuẩn bị vật màu tương phản.'],['Phát tín hiệu SOS','Ba ngắn, ba dài, ba ngắn. Thiết bị có thể phát âm và nháy màn hình sau khi bạn bấm bật.'],['Bảo toàn sức lực và pin','Dừng tín hiệu khi không cần. Công cụ này không gửi thông báo hay vị trí đến cứu hộ.']]}};
function situationButtons(modalMode=false){return`<div class="situation-grid">${[['lost','Bị lạc đường'],['water','Thiếu nước'],['cold','Mưa lạnh'],['snake','Nghi rắn cắn'],['battery','Sắp hết pin'],['signal','Cần tín hiệu SOS']].map(([id,label])=>`<button data-action="situation" data-id="${id}" data-modal="${modalMode}" class="situation ${situation===id?'active':''}">${ic(situations[id].icon)}<span>${label}</span></button>`).join('')}</div>`;}
function situationContent(){const s=situations[situation];return`<h2>${s.title}</h2><ol class="emergency-steps">${s.steps.map(([a,b])=>`<li><strong>${a}</strong><p>${b}</p></li>`).join('')}</ol>${s.tip?`<div class="notice">${ic('warning')}<p>${esc(TIPS.find(t=>t.id===s.tip).warning)}</p></div><a href="#/tip/${s.tip}" class="btn text" data-action="close-dialog">Đọc hướng dẫn đầy đủ${ic('arrow')}</a>`:''}${s.url?`<p class="source-row"><a href="${s.url}" target="_blank" rel="noopener">${s.source} ↗</a></p>`:''}`;}
function signalBox(){return`<h3>${ic('sos')}Tín hiệu SOS</h3><span class="sos-signal" aria-label="Ba ngắn ba dài ba ngắn">··· −−− ···</span><div class="emergency-controls"><button class="btn secondary" data-action="signal-audio">${ic('volume')}Bật còi SOS</button><button class="btn secondary" data-action="signal-light">${ic('sun')}Bật đèn SOS</button></div><p class="small muted" style="margin-top:13px;text-align:center" id="signal-status">Chỉ phát trên thiết bị này</p><div class="notice">${ic('warning')}<p>Đèn nháy có thể gây khó chịu với người nhạy sáng. Còi và đèn tiêu thụ pin. Không tự liên lạc với lực lượng cứu hộ.</p></div>`;}
function emergency(survival=false){shell(`<div class="title-row"><div><h1>${survival?'Bình tĩnh. Bạn có thể bắt đầu.':'Cẩm nang trợ giúp khẩn cấp'}</h1><p>Chọn tình huống. Ưu tiên an toàn và tìm hỗ trợ phù hợp.</p></div><button class="btn secondary" data-action="theme" data-value="${theme==='dark'?'light':'dark'}">${ic(theme==='dark'?'sun':'moon')}${theme==='dark'?'Giao diện sáng':'Tiết kiệm ánh sáng'}</button></div>${situationButtons()}<div class="emergency-layout"><section class="panel">${situationContent()}<div class="notice">${ic('warning')}<p>Hướng dẫn ban đầu không thay thế chăm sóc y tế hoặc chỉ dẫn của lực lượng cứu hộ. Khi có nguy hiểm, liên hệ trợ giúp ngay khi có thể.</p></div><div class="backup-actions"><button class="btn secondary" data-action="location">${ic('location')}Lấy vị trí thiết bị</button><span class="small muted" id="location-result"></span></div></section><aside class="panel sos-panel">${signalBox()}</aside></div>` ,survival?'survival':'emergency');}
function showDialog(title,body){stopSignal();modal.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Đóng">${ic('close')}</button></div>${body}`;if(!modal.open)modal.showModal();}
function openSOS(){showDialog('Bình tĩnh. Ưu tiên an toàn.',`${situationButtons(true)}<div id="sos-content">${situationContent()}</div><section class="sos-panel" style="margin-top:22px">${signalBox()}</section>`);}
function quiz(){quizAnswered=false;const q=QUIZ[quizIndex];shell(`<div class="quiz-layout"><div class="breadcrumb"><a href="#/">Khám phá</a>${ic('chevron')}Thử thách kỹ năng</div><div class="title-row"><div><h1>Nếu là bạn, bạn sẽ làm gì?</h1><p>Ba tình huống ngắn để nhớ lâu hơn.</p></div></div><section class="panel"><div class="quiz-count">Câu ${quizIndex+1} / ${QUIZ.length} · ${quizScore} câu đúng</div><h2>${q.q}</h2><div class="quiz-options">${q.a.map((a,i)=>`<button data-action="answer" data-id="${i}">${a}</button>`).join('')}</div><div id="quiz-feedback"></div></section></div>`,'quiz');}
async function handleAnswer(i){if(quizAnswered)return;quizAnswered=true;const q=QUIZ[quizIndex];if(i===q.correct)quizScore++;$$('.quiz-options button').forEach((b,j)=>{b.disabled=true;if(j===q.correct)b.classList.add('correct');else if(j===i)b.classList.add('wrong');});$('#quiz-feedback').innerHTML=`<div class="quiz-explanation"><strong>${i===q.correct?'Chính xác.':'Cùng nhớ lại nhé.'}</strong><p style="margin-top:6px">${q.why}</p></div><button class="btn" data-action="quiz-next">${quizIndex===QUIZ.length-1?'Xem kết quả':'Tình huống tiếp theo'}${ic('arrow')}</button>`;}
function finishQuiz(){write('quiz',{score:quizScore,total:QUIZ.length,date:new Date().toISOString()});shell(`<div class="quiz-layout panel"><div class="row" style="margin-bottom:20px">${ic('shield')}<h1>Bạn đã thêm một kỹ năng.</h1></div><div class="quality-number num">${quizScore} / ${QUIZ.length}</div><p>Câu trả lời đúng. Kết quả giúp ôn kiến thức, không phải chứng nhận kỹ năng sơ cứu.</p><div class="backup-actions"><button class="btn" data-action="restart-quiz">Thử lại${ic('rotate')}</button><a class="btn secondary" href="#/library">Khám phá cẩm nang</a></div></div>`,'quiz');}
function stopSignal(){clearTimeout(signalTimer);signalTimer=null;try{osc?.stop();}catch{}osc=null;audio?.close().catch(()=>{});audio=null;signalMode=null;document.body.classList.remove('screen-flash');modal.classList.remove('screen-flash');$$('[data-action="signal-audio"]').forEach(b=>b.innerHTML=ic('volume')+'Bật còi SOS');$$('[data-action="signal-light"]').forEach(b=>b.innerHTML=ic('sun')+'Bật đèn SOS');if($('#signal-status'))$('#signal-status').textContent='Chỉ phát trên thiết bị này';}
async function startSignal(mode){if(signalMode===mode){stopSignal();return;}stopSignal();signalMode=mode;const durations=[150,150,150,150,150,450,450,150,450,150,450,450,150,150,150,150,150,1050];let index=0;
 if(mode==='audio'){try{audio=new(window.AudioContext||window.webkitAudioContext)();await audio.resume();const gain=audio.createGain();gain.gain.value=.08;osc=audio.createOscillator();osc.frequency.value=880;osc.connect(gain);gain.connect(audio.destination);osc.start();const beep=()=>{if(!audio)return;gain.gain.setValueAtTime(index%2===0?.08:0,audio.currentTime);signalTimer=setTimeout(()=>{index=(index+1)%durations.length;beep();},durations[index]);};beep();}catch{stopSignal();toast('Trình duyệt chưa cho phép phát âm thanh.');return;}}
 else{const flash=()=>{if(signalMode!=='light')return;(modal.open?modal:document.body).classList.toggle('screen-flash',index%2===0);signalTimer=setTimeout(()=>{index=(index+1)%durations.length;flash();},durations[index]);};flash();}
 $$(`[data-action="signal-${mode}"]`).forEach(b=>b.innerHTML=ic('pause')+'Dừng tín hiệu');$('#signal-status').textContent=mode==='audio'?'Đang phát mã Morse bằng âm thanh 880 Hz':'Đang nháy màn hình theo mã Morse';}
const dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('tui-khon-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
dbPromise.catch(()=>{});
async function mediaPut(key,file){const db=await dbPromise;await new Promise((res,rej)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,key);tx.oncomplete=res;tx.onerror=()=>rej(tx.error);});}
async function mediaGet(key){const db=await dbPromise;return new Promise((res,rej)=>{const r=db.transaction('files').objectStore('files').get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}
async function showStoredMedia(key,target='#media-preview'){try{const f=await mediaGet(key);if(!f||!$(target))return;if(mediaUrl)URL.revokeObjectURL(mediaUrl);mediaUrl=URL.createObjectURL(f);$(target).innerHTML=`<p>${ic('check')}${esc(f.name)}</p>${f.type.startsWith('video/')?`<video src="${mediaUrl}" class="media-preview" controls playsinline></video>`:`<img src="${mediaUrl}" class="media-preview" alt="Minh họa do bạn chọn">`}`;}catch{toast('Không đọc được tệp đã lưu trên thiết bị.');}}
async function uploadMedia(file){if(!file)return;if(!['video/mp4','video/webm','image/jpeg','image/png','image/webp'].includes(file.type)||file.size>30*1024*1024){toast('Chọn đúng định dạng và tệp không quá 30 MB.');return;}if(file.type.startsWith('video/')){const seconds=await new Promise(resolve=>{const v=document.createElement('video'),url=URL.createObjectURL(file);v.preload='metadata';v.onloadedmetadata=()=>{URL.revokeObjectURL(url);resolve(v.duration);};v.onerror=()=>{URL.revokeObjectURL(url);resolve(Infinity);};v.src=url;});if(!Number.isFinite(seconds)||seconds>60){toast('Clip cần đọc được và dài không quá 60 giây.');return;}}
try{const key='media-'+Date.now();await mediaPut(key,file);draft.mediaKey=key;draft.mediaName=file.name;write('draft',draft);await showStoredMedia(key);refreshQuality();toast('Đã lưu tệp minh họa trên thiết bị.');}catch{toast('Không đủ bộ nhớ hoặc trình duyệt không cho lưu tệp.');}}
async function checkPacks(){try{const c=await caches.open('tk-meta-v1');const r=await c.match('packs');installedPacks=r?await r.json():[];}catch{installedPacks=[];}}
const assetFiles=['./','index.html','style.css','data.js','app.js','stage.js','manifest.webmanifest','handbook.txt','assets/icon.svg','assets/fonts.css','assets/three.min.js','assets/OrbitControls.js',...['forest','camp','mountain','kitchen','bottle','desk'].map(x=>'assets/'+x+'.jpg'),...Array.from({length:6},(_,i)=>'assets/font-'+i+'.woff2')];
async function downloadPack(id){if(!('serviceWorker'in navigator)||!('caches'in window)){toast('Trình duyệt chưa hỗ trợ lưu ngoại tuyến. Bạn có thể xuất bản .txt.');return;}const buttons=$$('[data-action="download-pack"]');buttons.forEach(b=>{b.disabled=true;b.innerHTML=ic('download')+'Đang lưu…';});try{await navigator.serviceWorker.ready;const c=await caches.open('tk-full-v1');for(let i=0;i<assetFiles.length;i++){const url=new URL(assetFiles[i],location.href.split('#')[0]);const r=await fetch(url,{cache:'reload'});if(!r.ok)throw Error('Thiếu tài nguyên '+assetFiles[i]);await c.put(url,r);const n=Math.round((i+1)/assetFiles.length*100);if($('#offline-status'))$('#offline-status').textContent=`Đang lưu ${i+1} / ${assetFiles.length} tài nguyên…`;if($('#offline-percent'))$('#offline-percent').textContent=n+'%';if($('#offline-bar'))$('#offline-bar').style.width=n+'%';}installedPacks=[...new Set([...installedPacks,id])];if(id==='all')installedPacks=['all','life','survival'];const meta=await caches.open('tk-meta-v1');await meta.put('packs',new Response(JSON.stringify(installedPacks),{headers:{'Content-Type':'application/json'}}));await navigator.storage?.persist?.();toast('Đã lưu trọn bộ tài nguyên. Cẩm nang sẵn sàng ngoại tuyến.');route();}catch(e){toast('Chưa tải đủ gói. Giữ kết nối và thử lại.');buttons.forEach(b=>{b.disabled=false;b.innerHTML=ic('download')+'Thử tải lại';});if($('#offline-status'))$('#offline-status').textContent='Tải chưa hoàn tất. Vui lòng thử lại khi có mạng.';}}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function handbook(){return 'TÚI KHÔN — CẨM NANG NGOẠI TUYẾN\nCập nhật nội dung: 19/10/2026\n\n'+TIPS.map(t=>t.title.toUpperCase()+'\nDụng cụ: '+t.tools.join(', ')+'\n'+t.steps.map((s,i)=>`${i+1}. ${s[0]}: ${s[1]}`).join('\n')+'\nLƯU Ý: '+t.warning+'\nNguồn: '+t.source+' '+(t.url||'')+'\n').join('\n')+'\nSOS: Dừng lại, giữ bình tĩnh, ở vị trí an toàn và liên lạc hỗ trợ khi có thể. Công cụ ngoại tuyến không tự gọi cứu hộ.\n';}
function showSources(){showDialog('Nguồn & cách biên soạn',`<p>Nội dung mẫu được biên soạn từ ý tưởng dự án và đối chiếu các nguồn dưới đây. Chưa có hội đồng chuyên gia thẩm định độc lập.</p><div class="source-list"><a target="_blank" rel="noopener" href="https://www.cdc.gov/water-emergency/about/">CDC — How to Make Water Safe in an Emergency ↗</a><a target="_blank" rel="noopener" href="https://www.who.int/health-topics/snakebite/snakebite">WHO — Snakebite ↗</a><a target="_blank" rel="noopener" href="https://www.nps.gov/articles/10essentials.htm">National Park Service — Ten Essentials ↗</a><a target="_blank" rel="noopener" href="https://www.nps.gov/articles/campfires.htm">National Park Service — Campfire Safety ↗</a><h3 style="margin-top:15px">Ảnh minh họa</h3><p>Ảnh phong cảnh và vật dụng từ Unsplash; ảnh chỉ minh họa chủ đề. Các bài hướng dẫn dùng mô hình 3D dựng bằng mã.</p>${[['forest','Rừng','photo-1448375240586-882707db888b'],['camp','Cắm trại','photo-1504280390367-361c6d9f38f4'],['mountain','Núi','photo-1464822759023-fed622ff2c3b'],['kitchen','Nhà bếp','photo-1556911220-bff31c812dba'],['bottle','Chai nước','photo-1602143407151-7111542de6e8'],['desk','Góc làm việc','photo-1496181133206-80ce9b88a853']].map(([id,title,photo])=>`<a href="https://images.unsplash.com/${photo}" target="_blank" rel="noopener">${title} · Unsplash ↗</a>`).join('')}<p>Be Vietnam Pro, Fraunces · Google Fonts. Three.js r128 · MIT.</p></div>`);}
function toolModal(){showDialog('Bạn đang có dụng cụ nào?',`<p>Gợi ý mẹo dùng ít nhất một vật dụng bạn chọn. Kiểm tra danh sách đầy đủ trước khi bắt đầu.</p><div class="tool-options" style="display:flex;flex-wrap:wrap;gap:9px;margin:22px 0">${[...new Set(TIPS.flatMap(t=>t.tools))].map(t=>`<button class="chip ${toolSelection.includes(t)?'active':''}" data-action="tool" data-value="${esc(t)}" aria-pressed="${toolSelection.includes(t)}">${ic('plus')}${esc(t)}</button>`).join('')}</div><button class="btn" data-action="apply-tools">Xem mẹo phù hợp${ic('arrow')}</button>`);}
function previewContribution(id){const c=contributions.find(x=>x.id===id);if(!c)return;showDialog(c.title||'Bản nháp',`<span class="tag warning">${c.status==='draft'?'Bản nháp':'Chờ thẩm định'} · Chỉ lưu trên thiết bị</span><p style="margin:15px 0">${esc(c.desc)}</p><p>Dụng cụ: ${esc(c.tools)}</p>${[1,2,3].map(i=>`<div class="review-section"><strong>Bước ${i}</strong><p>${esc(c['s'+i])}</p></div>`).join('')}<div class="notice">${ic('warning')}<p>${esc(c.warning||'Chưa bổ sung lưu ý.')}</p></div><p class="source-row">Nguồn: ${esc(c.source)}</p>${c.mediaKey?'<div id="contribution-media"></div>':''}`);if(c.mediaKey)showStoredMedia(c.mediaKey,'#contribution-media');}
function route(){stage?.dispose();stage=null;clearInterval(autoTimer);autoTimer=null;stopSignal();detailTip=null;if(modal.open)modal.close();const parts=location.hash.replace(/^#\/?/,'').split('/');const r=parts[0]||'home';if(r==='home')home();else if(r==='library')library();else if(r==='saved')library(true);else if(r==='tip')detail(parts[1]);else if(r==='practice'){detail(parts[1]||'water');if(detailTip){const index=TIPS.indexOf(detailTip);$('#main').insertAdjacentHTML('afterbegin',`<div class="practice-pager"><a class="btn secondary" href="#/practice/${TIPS[(index-1+TIPS.length)%TIPS.length].id}">← Mẹo trước</a><div><strong>Thực hành nhanh</strong><p>${index+1} / ${TIPS.length} mẹo · 3 bước tương tác</p></div><a class="btn secondary" href="#/practice/${TIPS[(index+1)%TIPS.length].id}">Mẹo tiếp →</a></div>`);}}else if(r==='manage')manage();else if(r==='contribute')contribution();else if(r==='offline')offline();else if(r==='survival'||r==='emergency')emergency(r==='survival');else if(r==='quiz'){quizIndex=0;quizScore=0;quiz();}else shell(empty('Trang này chưa có.','Quay lại thư viện để tiếp tục khám phá.'),'missing');document.title=(r==='tip'&&detailTip?detailTip.title+' · ':'')+'Túi Khôn — Mẹo nhỏ, bản lĩnh lớn';window.scrollTo(0,0);}
function updateLibraryResults(){const list=filteredTips();if($('#tip-results'))$('#tip-results').innerHTML=list.length?list.map(tipCard).join(''):empty('Chưa tìm thấy mẹo phù hợp.','Thử từ khóa ngắn hơn hoặc bỏ bớt bộ lọc.');if($('#result-count'))$('#result-count').textContent=`${list.length} mẹo${query?' cho “'+query+'”':''}`;}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,value=b.dataset.value;
if(a==='menu'){$('.navline').classList.toggle('open');return;}
if(a==='theme'){theme=value;write('theme',theme);document.documentElement.dataset.theme=theme;$$('.mode-switch button').forEach(x=>{x.classList.toggle('selected',x.dataset.value===theme);x.setAttribute('aria-pressed',x.dataset.value===theme);});if(location.hash.includes('survival')||location.hash.includes('emergency'))route();return;}
if(a==='save'){const next=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];if(!write('saved',next))return;saved=next;const yes=saved.includes(id);$$(`[data-action="save"][data-id="${id}"]`).forEach(x=>{x.classList.toggle('saved',yes);x.setAttribute('aria-pressed',yes);if(x.querySelector('span'))x.querySelector('span').textContent=yes?'Đã lưu':'Lưu mẹo';else x.setAttribute('aria-label',(yes?'Bỏ lưu ':'Lưu ')+TIPS.find(t=>t.id===id).title);});toast(yes?'Đã thêm vào sổ tay của bạn.':'Đã bỏ lưu mẹo.');if(location.hash==='#/saved')library(true);return;}
if(a==='category'){currentCat=id;$$('[data-action="category"]').forEach(x=>{x.classList.toggle('active',x.dataset.id===id);x.setAttribute('aria-pressed',x.dataset.id===id);});if(location.hash==='#/library')updateLibraryResults();else $('#tip-results').innerHTML=filteredTips().slice(0,4).map(tipCard).join('');return;}
if(a==='tool'){toolSelection=toolSelection.includes(value)?toolSelection.filter(x=>x!==value):[...toolSelection,value];$$('[data-action="tool"]').forEach(x=>{x.classList.toggle('active',toolSelection.includes(x.dataset.value));x.setAttribute('aria-pressed',toolSelection.includes(x.dataset.value));});return;}
if(a==='tool-search'||a==='apply-tools'){currentCat='all';query='';if(modal.open)modal.close();if(location.hash==='#/library')library();else location.hash='/library';return;}
if(a==='clear-tools'){toolSelection=[];library();return;}
if(a==='tool-modal'){toolModal();return;}
if(a==='step'){clearInterval(autoTimer);autoTimer=null;setStep(Number(b.dataset.step));const p=$('[data-action="autoplay"]');p.innerHTML=ic('play')+'<span>Tự động chạy</span>';return;}
if(a==='autoplay'){if(autoTimer){clearInterval(autoTimer);autoTimer=null;b.innerHTML=ic('play')+'<span>Tự động chạy</span>';}else{autoTimer=setInterval(()=>setStep((activeStep+1)%3),4200);b.innerHTML=ic('pause')+'<span>Tạm dừng</span>';}return;}
if(a==='reset-stage'){stage?.reset();return;}
if(a==='fullscreen'){const el=$('#stage');if(document.fullscreenElement)document.exitFullscreen?.();else el.requestFullscreen?.().catch(()=>toast('Thiết bị không hỗ trợ toàn màn hình.'));return;}
if(a==='share'){const t=TIPS.find(x=>x.id===id),url=location.href.split('#')[0]+'#/tip/'+id;try{await navigator.clipboard.writeText(url);toast('Đã sao chép liên kết mẹo.');}catch{showDialog('Chia sẻ mẹo',`<p>${esc(t.title)}</p><label class="form-field"><span>Liên kết</span><input readonly value="${esc(url)}" onfocus="this.select()"></label>`);}return;}
if(a==='sos'){situation='lost';openSOS();return;}
if(a==='close-dialog'){modal.close();return;}
if(a==='situation'){situation=id;stopSignal();if(b.dataset.modal==='true')openSOS();else emergency(location.hash==='#/survival');return;}
if(a==='signal-audio'){startSignal('audio');return;}if(a==='signal-light'){startSignal('light');return;}
if(a==='location'){if(!navigator.geolocation){toast('Thiết bị không hỗ trợ vị trí.');return;}b.disabled=true;$('#location-result').textContent='Đang xác định…';navigator.geolocation.getCurrentPosition(p=>{b.disabled=false;$('#location-result').textContent=`${p.coords.latitude.toFixed(5)}, ${p.coords.longitude.toFixed(5)} · sai số ±${Math.round(p.coords.accuracy)} m`;},()=>{b.disabled=false;$('#location-result').textContent='Chưa lấy được vị trí. Kiểm tra quyền và tín hiệu GPS.';},{enableHighAccuracy:true,timeout:15000,maximumAge:30000});return;}
if(a==='save-draft'){if(saveContribution('draft'))toast('Đã lưu bản nháp trên thiết bị.');return;}
if(a==='wizard-back'){captureDraft();wizardStep=Math.max(0,wizardStep-1);contribution();return;}
if(a==='wizard-goto'){captureDraft();wizardStep=Number(b.dataset.step);contribution();return;}
if(a==='manage-filter'){manageFilter=id;manage();return;}
if(a==='edit-contribution'){draft={...contributions.find(c=>c.id===id)};write('draft',draft);wizardStep=0;location.hash='/contribute';return;}
if(a==='preview-contribution'){previewContribution(id);return;}
if(a==='download-pack'){await downloadPack(id);return;}
if(a==='download-text'){download('Tui-Khon-Cam-Nang.txt',handbook());toast('Đã xuất cẩm nang văn bản.');return;}
if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else showDialog('Cài Túi Khôn trên thiết bị',`<p>Trong Chrome/Edge, mở menu trình duyệt và chọn “Cài ứng dụng” hoặc “Thêm vào màn hình chính”. Trên iPhone/iPad, mở bằng Safari, chọn Chia sẻ → Thêm vào MH chính.</p><div class="notice">${ic('download')}<p>Nhớ tải gói ngoại tuyến trong cẩm nang sau khi cài.</p></div>`);return;}
if(a==='cache-info'){if(navigator.storage?.estimate){const s=await navigator.storage.estimate();$('#storage-info').textContent=`Đã dùng khoảng ${(s.usage/1024/1024).toFixed(1)} MB trên tên miền này.`;}else toast('Trình duyệt chưa cung cấp dung lượng.');return;}
if(a==='export'){download('Tui-Khon-Du-Lieu.json',JSON.stringify({version:1,name,saved,completed,contributions,feedback:read('feedback',[]),exported:new Date().toISOString()},null,2),'application/json');toast('Đã xuất dữ liệu văn bản. Tệp video/ảnh vẫn ở thiết bị này.');return;}
if(a==='sources'){showSources();return;}
if(a==='about'){showDialog('Mẹo nhỏ, bản lĩnh lớn.',`<p>Túi Khôn là cẩm nang kỹ năng đời sống và sinh tồn, kết hợp hướng dẫn ngắn với mô hình 3D tương tác.</p><div class="review-section"><h3>Bản trải nghiệm đầy đủ luồng</h3><p>Tìm kiếm, lưu mẹo, tiến độ học, câu hỏi tình huống, tải ngoại tuyến và lưu bài đóng góp đều chạy trên thiết bị.</p><p>Chưa kết nối máy chủ tài khoản, kho video cộng đồng, AI hay hội đồng thẩm định. Không dùng điểm đầy đủ biểu mẫu như một chứng nhận an toàn.</p></div>`);return;}
if(a==='profile'){showDialog('Góc của bạn',`<form id="profile-form"><label class="form-field"><span>Tên hiển thị</span><input name="name" value="${esc(name)}" required maxlength="50"></label><label class="form-field"><span>Giao diện</span><select name="theme"><option value="light" ${theme==='light'?'selected':''}>Đời sống · sáng</option><option value="dark" ${theme==='dark'?'selected':''}>Sinh tồn · tối</option></select></label><button class="btn" type="submit">Lưu thay đổi</button><p class="small" style="margin-top:15px">Hồ sơ cục bộ, không yêu cầu đăng nhập.</p></form>`);return;}
if(a==='answer'){handleAnswer(Number(id));return;}if(a==='quiz-next'){if(quizIndex===QUIZ.length-1)finishQuiz();else{quizIndex++;quiz();}return;}if(a==='restart-quiz'){quizIndex=0;quizScore=0;quiz();return;}
});
document.addEventListener('submit',e=>{if(e.target.matches('#search-form,#library-search')){e.preventDefault();query=new FormData(e.target).get('q').trim();currentCat='all';if(location.hash==='#/library')library();else location.hash='/library';}else if(e.target.id==='contribution-form'){e.preventDefault();captureDraft();if(wizardStep<3){wizardStep++;contribution();window.scrollTo(0,0);}else if(saveContribution('pending')){draft={};write('draft',{});wizardStep=0;location.hash='/manage';toast('Đã lưu bản gửi chờ thẩm định trên thiết bị.');}}else if(e.target.id==='profile-form'){e.preventDefault();const f=new FormData(e.target);name=f.get('name').trim()||'Bạn khám phá';theme=f.get('theme');write('name',name);write('theme',theme);modal.close();route();toast('Đã lưu hồ sơ.');}else if(e.target.id==='feedback-form'){e.preventDefault();const text=new FormData(e.target).get('feedback').trim();const notes=read('feedback',[]);if(write('feedback',[...notes,{tip:detailTip.id,text,date:new Date().toISOString()}])){e.target.reset();$('#feedback-notes').innerHTML=feedbackNotes(detailTip.id);toast('Đã lưu góp ý trên thiết bị.');}}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.closest('#contribution-form')){captureDraft();refreshQuality();}if(e.target.closest('#library-search')){query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(updateLibraryResults,140);}});
document.addEventListener('change',async e=>{if(e.target.dataset.complete){const id=e.target.dataset.complete;completed=e.target.checked?[...new Set([...completed,id])]:completed.filter(x=>x!==id);write('completed',completed);toast(e.target.checked?'Đã đánh dấu kỹ năng bạn đã đọc.':'Đã bỏ đánh dấu.');}if(e.target.id==='media-upload')uploadMedia(e.target.files[0]);if(e.target.id==='import-data'){const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error();const d=JSON.parse(await file.text());if(d.version!==1||!Array.isArray(d.saved)||!Array.isArray(d.completed))throw Error();const allowed=TIPS.map(t=>t.id);saved=[...new Set([...saved,...d.saved.filter(x=>allowed.includes(x))])];completed=[...new Set([...completed,...d.completed.filter(x=>allowed.includes(x))])];write('saved',saved);write('completed',completed);if(Array.isArray(d.contributions)){const safe=d.contributions.filter(c=>c&&typeof c.id==='string'&&typeof c.title==='string').map(c=>Object.fromEntries(Object.entries(c).filter(([k,v])=>['id','title','cat','tools','desc','s1','s2','s3','warning','source','updated','status'].includes(k)&&typeof v==='string'))).map(c=>({...c,status:c.status==='draft'?'draft':'pending',updated:Number.isNaN(Date.parse(c.updated))?new Date().toISOString():c.updated}));contributions=[...contributions,...safe.filter(c=>!contributions.some(x=>x.id===c.id))];write('contributions',contributions);}if(Array.isArray(d.feedback)){const notes=d.feedback.filter(n=>n&&allowed.includes(n.tip)&&typeof n.text==='string').map(n=>({tip:n.tip,text:n.text.slice(0,1000),date:typeof n.date==='string'?n.date:new Date().toISOString()}));write('feedback',[...read('feedback',[]),...notes]);}route();toast('Đã nhập và hợp nhất dữ liệu.');}catch{toast('Tệp dữ liệu chưa đúng định dạng Túi Khôn.');}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();if($('#global-search')?.offsetParent)$('#global-search').focus();else{location.hash='/library';setTimeout(()=>$('#library-search input')?.focus(),20);}}});
modal.addEventListener('close',()=>{stopSignal();if(mediaUrl){URL.revokeObjectURL(mediaUrl);mediaUrl=null;}});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopSignal();clearInterval(autoTimer);autoTimer=null;const b=$('[data-action="autoplay"]');if(b)b.innerHTML=ic('play')+'<span>Tự động chạy</span>';}});
window.addEventListener('hashchange',route);window.addEventListener('online',()=>{if($('#connection-label'))$('#connection-label').textContent='Sẵn sàng khám phá';toast('Đã có kết nối mạng.');});window.addEventListener('offline',()=>{if($('#connection-label'))$('#connection-label').textContent='Đang ngoại tuyến';toast('Đang ngoại tuyến. Dùng các cẩm nang đã tải.');});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>toast('Chưa bật được ngoại tuyến. Hãy dùng bản cẩm nang .txt.'));
checkPacks().then(route);
})();
